def _post_create() -> None:
    bind = op.get_bind()
    # Append-only audit log: block UPDATE always; DELETE only for the retention job, which sets
    # anm.audit_retention = 'on' for its own transaction.
    op.execute("""
    CREATE OR REPLACE FUNCTION anm_audit_protect() RETURNS trigger AS $$
    BEGIN
      IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'audit_logs is append-only';
      END IF;
      IF TG_OP = 'DELETE' AND coalesce(current_setting('anm.audit_retention', true), 'off') <> 'on' THEN
        RAISE EXCEPTION 'audit_logs rows can only be removed by the retention job';
      END IF;
      RETURN OLD;
    END $$ LANGUAGE plpgsql;
    """)
    op.execute("CREATE TRIGGER audit_logs_protect BEFORE UPDATE OR DELETE ON audit_logs "
               "FOR EACH ROW EXECUTE FUNCTION anm_audit_protect()")
    has_ts = bind.exec_driver_sql(
        "SELECT count(*) FROM pg_available_extensions WHERE name = 'timescaledb'").scalar()
    if has_ts:
        op.execute("CREATE EXTENSION IF NOT EXISTS timescaledb")
        for table, keep in TIMESERIES.items():
            op.execute(f"SELECT create_hypertable('{table}', 'ts', chunk_time_interval => INTERVAL '1 day', "
                       f"migrate_data => true, if_not_exists => true)")
            op.execute(f"SELECT add_retention_policy('{table}', INTERVAL '{keep}', if_not_exists => true)")
        op.execute("ALTER TABLE port_metrics SET (timescaledb.compress, "
                   "timescaledb.compress_segmentby = 'switch_id, if_index')")
        op.execute("SELECT add_compression_policy('port_metrics', INTERVAL '3 days', if_not_exists => true)")


